// SEA CUAL SEA la rama: en un rehorneo con caché fría incluía el horneado (304 ms) y en verifica() medía la
// siembra exacta (297 ms). Se leía 322 ms de fusión y la fusión de verdad no se había medido nunca. Ley VIII:
// una medida que no puede distinguir tres caminos no es una medida.
const cero = () => { C.ticks=0; C.cbl=0; C.rehorneos=0; C.subidas=0; C.bytes=0; C.cambiosSub=0;
