  const orig = window[nombre];
  if(typeof orig !== 'function'){
    if(opcional) return false;
    throw new Error('luz-quietas: no encuentro ' + nombre + '() — ¿app.js cambió?');
  }
  const nueva = function(){ return hacer(orig, arguments); };
  nueva._lqOrig = orig;
  window[nombre] = nueva;
  return true;
}

