  S.vistas.clear(); S.vistasB.clear(); S.quietas = []; S.sig = null; S.lvQ = 0; S.moviles = null;
  S.hasGlowAntes = null;
  // v7 · LA CACHÉ SOBREVIVE A off(). La v6 la tiraba, así que cada `on()` de un A/B pagaba otro horneo de
  // ~328 ms: las «5 horneadas» del informe del dueño eran suyas, de tanto medir. La caché es memoria NUESTRA,
  // no estado del motor: conservarla no rompe la regla 4 (off() sigue devolviendo el motor byte a byte), sólo
  // deja 18 MB ocupados. Se sueltan a mano con game.luzQuietas.suelta().
  S.k.sucia = false;
  S.sembrado = false;
  // ⚠️ EL ORDEN IMPORTA Y ANTES ESTABA AL REVÉS (v6). `mcComputeBlockLight` empieza por el atajo
  // `if(!mc.hasGlow || lv0<=0) return`, ANTES del `BL.fill(0)`. Si primero devolvemos `hasGlow` a `false`
  // —que es lo que vale en un mapa cuyas únicas luces son estrellas de voxelesUI— el original se va por el
  // atajo, NO borra nada, y la luz de las estrellas se queda HORNEADA en `mc.blockLight` para siempre. Así
  // que se borra con `hasGlow` todavía en alto y sólo DESPUÉS se le pregunta al motor cuánto vale de verdad.
  // Las dos firmas: la caja vuelve a llevar las estrellas y el mundo tiene que soltarlas. Si sólo se invalida
  // una, la otra se sigue pintando con sus bytes viejos y medio mapa cambia de brillo de golpe.
  mc.hasGlow = true;
  mc._dynSig = null; mc._blEmiSig = null;
  if(mc.grid) mcComputeBlockLight();                                   // ahora sí: BL.fill(0) + siembra real
  if(typeof mcRecomputeHasGlow === 'function') mcRecomputeHasGlow();   // deshace el forzado, sin suponer nada
  mc._blkTexDirty = true;                                              // que la GPU vea el campo ya limpio
  cero();
}

// ── el reparto: qué se mueve y qué no ───────────────────────────────────────────────────────────────────────
// Esto corre EN CADA FRAME, ande o no ande el jugador: es el único coste fijo del módulo, así que lleva su
// propio reloj (`C.msCenso`, publicado por tick en estado()). La v4 construía una CADENA por luz y por frame
// ("qx,qy,qz,n") y un Map nuevo: 236 estrellas a 200 fps = 47.000 cadenas por segundo de basura, pagadas
// también estando quieto. v5: clave numérica exacta y dos Maps que se turnan ⇒ cero asignaciones por frame.
function repartir(todas){
  const t0 = performance.now();
  const antes = S.vistas, ahora = S.vistasB;
  ahora.clear();
  const moviles = [], quietas = [];
  let lvQ = 0;
  for(let i = 0; i < todas.length; i += 4){
    const x = todas[i], y = todas[i+1], z = todas[i+2], n = todas[i+3];
    // 15 bits por eje (±128 bloques a 1/128) + 6 para el nivel = 51 bits: entero EXACTO en un double. Dos
    // luces separadas justo 256 bloques compartirían contador; en un mundo de 96 no existe ese par.
    const qx = Math.round(x*QPOS) & 32767, qy = Math.round(y*QPOS) & 32767, qz = Math.round(z*QPOS) & 32767;
    const k = ((qx*32768 + qy)*32768 + qz)*64 + (n & 63);
    const veces = (antes.get(k) || 0) + 1;
    ahora.set(k, veces);
    if(veces >= API.tras){ quietas.push(x, y, z, n); if(n > lvQ) lvQ = n|0; }
    else moviles.push(x, y, z, n);
  }
  // Lo que ya no aparece desaparece del censo: una luz que se APAGA deja de estar quieta, y ese es justo el
  // fallo silencioso que caza la Ley VII (una estrella apagada que sigue alumbrando porque nadie rehorneó).
  S.vistas = ahora; S.vistasB = antes;

  let sig = quietas.length;
  for(let i = 0; i < quietas.length; i++) sig = (sig*31 + Math.round(quietas[i]*QPOS)) | 0;
  if(sig !== S.sig){
    const habia = S.quietas.length;
    S.sig = sig; S.quietas = quietas; S.lvQ = lvQ;
    mc._blEmiSig = null;      // el conjunto quieto cambió ⇒ el campo del mundo hay que rehacerlo
    S.pideRehorneo = true;    // …y hay que PEDIRLO (fallo 4 de la v2), que invalidar la firma no llama a nadie
    // Fallo 3 de la v2: al quedarse sin quietas hay que DEVOLVER `hasGlow`, o el mundo se queda con la luz
    // vieja pegada, con la textura marcándose sucia y sin nadie que borre el campo.
    if(!quietas.length && habia && typeof mcRecomputeHasGlow === 'function'){
      mcRecomputeHasGlow(); S.hasGlowAntes = null; S.sembrado = false;
    }
  }
  C.msCenso += performance.now() - t0;
  return moviles;
}

// ── la siembra en el campo del MUNDO ────────────────────────────────────────────────────────────────────────
// Ni una línea de BFS: `mcCampoLuz` + `mcLuzBuckets` + `mcLuzSiembra` + `mcLuzDifunde` son las de app.js, las
// mismas que acaba de usar mcComputeBlockLight para las antorchas. Lo único propio son los buckets, que van
// dimensionados al alcance de las estrellas (37) y no al lv0 del mundo (15).
function sembrarEn(BL, BD, OR, DI, MX){
  if(!BL || !BD || !S.quietas.length) return false;
  const dim = mc.dim;
  const focus = Math.max(0, Math.min(1, mc.glowFocus || 0));
  const lv0 = Math.max(1, S.lvQ|0);
  const Cx = mcCampoLuz(BL, BD, 0, 0, 0, dim.x, dim.y, dim.z, OR, DI, MX);
  const PASA = mcTablaLuz(), buckets = mcLuzBuckets(lv0);
  for(let i = 0; i < S.quietas.length; i += 4){
    const fx = S.quietas[i], fy = S.quietas[i+1], fz = S.quietas[i+2], n = S.quietas[i+3]|0;
    // Sin haz y sin color propio (blanco cálido), que es exactamente como entraban en la caja dinámica
    // (mcDynSync las mete con haz 0,0,0 y color −1). Con su posición FINA: Mandamiento 4, la misma luz.
    mcLuzSiembra(Cx, PASA, buckets, n, focus, Math.floor(fx), Math.floor(fy), Math.floor(fz),
                 null, 0, null, fx, fy, fz);
  }
  mcLuzDifunde(Cx, PASA, buckets, lv0, focus);
  return true;
}
// Sembrar DIRECTAMENTE sobre el campo vivo: el camino exacto y caro (264 ms con 238 estrellas). Es lo que hacía
// la v3 en cada rehorneo, y lo que ahora sólo se usa para rehacer la caché y para verifica().
function sembrarQuietas(){
  return sembrarEn(mc.blockLight, mc.blockLightDir, mc.blockLightOrg, mc.blockLightDist, mc.blockLightMax);
}

// ── v4 · LA CACHÉ DE LAS QUIETAS ────────────────────────────────────────────────────────────────────────────
// El problema que resuelve, MEDIDO: `mcComputeBlockLight` hace `BL.fill(0)` (app.js:11113) y rehornea el campo
// del mundo DESDE CERO en cada edición. Con las estrellas dentro, eso son 238 semillas de alcance 37 = ~50 M de
// relajaciones = 268 ms de congelón por bloque puesto o roto. Y son ESTÁTICAS: estábamos recalculando cientos de
// veces algo que no cambia.
// Lo que se guarda es el campo de las quietas SOLAS (sin el mundo): así el mundo puede rehornearse cuando quiera
// —él es barato, 3,3 ms— y las estrellas se le funden encima.
function tamCampo(){ const d = mc.dim; return d.x*d.y*d.z; }

function cacheVale(){ return !!(S.k.idx && S.k.n === tamCampo()); }

function horneaCache(){
  const N = tamCampo(), K = S.k;
  const t0 = performance.now();
  // Andamio de usar y tirar: el BFS de app.js escribe sobre campos DENSOS, así que se le da uno. Vive lo que
  // dura el horneado; lo que se queda guardado es la lista compacta de abajo.
  const BL = new Uint8Array(N*4), BD = new Int8Array(N*3);
  const OR = new Int16Array(N*3), DI = new Uint16Array(N), MX = new Uint8Array(N);
  sembrarEn(BL, BD, OR, DI, MX);
  let M = 0;
  for(let i = 0; i < N; i++) if(BL[i*4+3]) M++;
  const idx = new Uint32Array(M), bl = new Uint8Array(M*4), bd = new Int8Array(M*3);
  const or = new Int16Array(M*3), di = new Uint16Array(M), mx = new Uint8Array(M);
  let m = 0;
  for(let i = 0; i < N; i++){
    const j = i*4; if(!BL[j+3]) continue;
    const p = m*4, t = i*3, u = m*3;
    idx[m] = i;
    bl[p] = BL[j]; bl[p+1] = BL[j+1]; bl[p+2] = BL[j+2]; bl[p+3] = BL[j+3];
    bd[u] = BD[t]; bd[u+1] = BD[t+1]; bd[u+2] = BD[t+2];
    or[u] = OR[t]; or[u+1] = OR[t+1]; or[u+2] = OR[t+2];
    di[m] = DI[i]; mx[m] = MX[i];
    m++;
  }
  K.idx = idx; K.bl = bl; K.bd = bd; K.or = or; K.di = di; K.mx = mx;
  K.n = N; K.celdas = M;
  K.ms = performance.now() - t0;
  K.sig = S.sig; K.gen = mc.gridGen|0; K.sucia = false; K.horneos = (K.horneos|0) + 1;
  C.msHornear = K.ms;
  return K.ms;
}

// La fusión, celda a celda. Ley VI: una celda guarda UN emisor, así que quien tiene más nivel (`BL[j+3]`, en
// subniveles) se lleva TAMBIÉN su dirección de haz, su origen, su camino y su pleno — copiarle el nivel y
// dejarle al otro el OR/DI/MX es exactamente el bug que arregló BUG-GLOW8h. El tinte va por `max` en cada canal,
// que es lo que hace `pinta` en app.js cuando dos emisores se solapan.
function fusionaCache(){
  const K = S.k, BL = mc.blockLight, BD = mc.blockLightDir;
  const OR = mc.blockLightOrg, DI = mc.blockLightDist, MX = mc.blockLightMax;
  if(!K.idx || !BL || K.n !== (BL.length >> 2)) return -1;
  const t0 = performance.now();
  const idx = K.idx, bl = K.bl, bd = K.bd, or = K.or, di = K.di, mx = K.mx;
  const M = idx.length, conOR = !!(OR && DI && MX);
  let ganadas = 0;
  for(let m = 0; m < M; m++){
    const i = idx[m], p = m*4, j = i*4, v = bl[p+3];
    if(bl[p]   > BL[j])   BL[j]   = bl[p];      // el tinte va por `max` en cada canal, como `pinta` en app.js
    if(bl[p+1] > BL[j+1]) BL[j+1] = bl[p+1];
    if(bl[p+2] > BL[j+2]) BL[j+2] = bl[p+2];
    if(v <= BL[j+3]) continue;                  // el mundo gana la celda: se queda con su dueño ENTERO
    BL[j+3] = v;
    const t = i*3, u = m*3;
    BD[t] = bd[u]; BD[t+1] = bd[u+1]; BD[t+2] = bd[u+2];
    if(conOR){ OR[t] = or[u]; OR[t+1] = or[u+1]; OR[t+2] = or[u+2]; DI[i] = di[m]; MX[i] = mx[m]; }
    ganadas++;
  }
  K.ultGanadas = ganadas;
  C.msFusion = performance.now() - t0;   // AISLADO: éste es el precio de verdad de reusar la caché
  C.nFusiones = (C.nFusiones|0) + 1; C.msFusionTot = (C.msFusionTot||0) + C.msFusion;
  return ganadas;
}

// ── instalación ─────────────────────────────────────────────────────────────────────────────────────────────
function instalar(){
  // 1 · marca el tick. El censo tiene que avanzar UNA vez por frame; si lo avanzara también un diagnóstico,
  //     abrir el informe haría «quietas» a luces que se mueven.
  envolver('mcDynSync', (orig, a) => {
    S.enTick = true; C.ticks++;
    try { return orig.apply(null, a); }
    finally {
      S.enTick = false;
      // FALLO 4 DE LA v2 — el que hacía que la medida mintiera. `repartir()` invalidaba `mc._blEmiSig`, pero
      // en este mapa NADIE vuelve a llamar a `mcComputeBlockLight` (0.005 llamadas/tick: sólo la de instalar,
      // cuando el censo aún estaba vacío). Resultado: las 236 estrellas salían de la caja dinámica y no
      // entraban en el campo del mundo. 61 → 217 fps con las estrellas sin alumbrar nada, que no es el
      // ticket. El rehorneo se pide AQUÍ, al cerrar el tick: fuera del censo (nada de reentrar en
      // mcVoxUILuces) y sólo cuando el conjunto quieto ha cambiado de verdad, que es lo que manda la Ley VII.
      if(S.pideRehorneo){ S.pideRehorneo = false; if(mc.grid) mcComputeBlockLight(); }
      // v4 · EL REFRESCO DIFERIDO. Una edición dejó la caché vieja cerca del bloque tocado. Rehacerla exacta
      // cuesta lo que costaba antes (264 ms), así que se hace UNA sola vez y cuando el jugador ha parado:
      // levantar una pared de 20 bloques paga un refresco, no veinte. ⚠️ Entre la edición y este refresco hay
      // celdas con la luz de las estrellas de ANTES de la edición: `verifica()` dice cuántas y cuánto.
      else if(S.k.sucia && performance.now() - S.k.tocada > API.refresco){
        S.k.sucia = false; horneaCache(); C.refrescos++;
        mc._blEmiSig = null; if(mc.grid) mcComputeBlockLight();
      }
    }
  });

  // 2 · LA COSTURA PRINCIPAL. Devolver sólo las móviles encoge la caja de mcDynBake sin tocar mcDynSync ni
  //     mcDynBake: la caja es la unión de las semillas que le llegan, y ya no le llegan las estrellas.
  envolver('mcVoxUILuces', (orig) => {
    const todas = orig();
    if(!S.enTick) return S.moviles || todas;    // diagnóstico: no avanza el censo
    S.enTick = false;                           // una sola vez por tick, aunque el tick la llame dos veces
    S.todas = todas;
    return (S.moviles = repartir(todas));
  });

  // 3 · el paso del campo se sigue decidiendo con el alcance de las quietas dentro (punto C de la cabecera).
  //     OPCIONAL: la función es de REQ-LUZ4 y puede no estar en este app.js.
  S.conSub = envolver('mcLuzSubAjusta', (orig, a) => {
    const antes = MC_LUZ_SUB;
    const r = orig(Math.max(a[0]|0, S.lvQ|0));
    if(MC_LUZ_SUB !== antes) C.cambiosSub++;   // si esto sube sin parar, hay realimentación (fallo 1 de la v2)
    return r;
  }, true);

  // 4 · tras rehornear el mundo, las quietas encima. Si el original salió por su firma (no-op), el campo ya
  //     las lleva de la vez pasada y aquí no hay nada que hacer: ése es justo el ahorro del ticket.
  envolver('mcComputeBlockLight', (orig) => {
    C.cbl++;
    // v5 · EL INTERRUPTOR QUE SEPARA LAS DOS MITADES DEL TICKET. `emiten:false` deja la mitad barata (las
    // quietas fuera de la caja de mcDynBake) y quita la cara (que alumbren el mundo: hasGlow forzado + los
    // 12 MB del campo de bloque muestreados por píxel y por frame). Sirve para CONTESTAR con números a «se
    // supone que esto sube los fps»: off / on+emiten / on-emiten son tres escenas MEDIBLES, y sólo las dos
    // primeras se ven igual. Ley VIII y la regla del dueño: una feature cara se conmuta.
    if(!S.quietas.length || !API.emisoras) return orig();
    if(S.hasGlowAntes === null) S.hasGlowAntes = mc.hasGlow;
    mc.hasGlow = true;          // un mapa cuyo ÚNICO emisor es una estrella se iba por el atajo de «sin emisivos»
    // Fallo 2 de la v2: el original marca `_blkTexDirty=true` en su PRIMERA línea, antes de mirar su firma.
    // Con `hasGlow` forzado eso significa subir el campo del mundo entero a la GPU en cada llamada, aunque no
    // haya cambiado un byte — invisible en los fps y letal para el navegador. Se guarda para devolverlo.
    const dirtyA = mc._blkTexDirty;
    const sigA = mc._blEmiSig, genA = mc._blGridGen, blA = mc.blockLight;
    const t0 = performance.now();
    const r = orig();
    const t1 = performance.now();
    const rehorneo = (mc._blEmiSig !== sigA) || (mc._blGridGen !== genA) || (mc.blockLight !== blA);
    if(rehorneo){
      let sembrado;
      C.msHornear = 0; C.msFusion = 0; C.msExacto = 0;   // cada rama pone SU reloj; el que no corre queda en 0
      if(S.exacto){
        const te = performance.now();
        sembrado = sembrarQuietas();           // el camino caro y exacto: sólo verifica() y el refresco diferido
        C.msExacto = performance.now() - te;
      } else if(!cacheVale() || S.k.sig !== S.sig){
        horneaCache();                          // cambió QUIÉN está quieto: la caché ya no vale para nada
        sembrado = fusionaCache() >= 0;
      } else {
        // Cambió la TOPOLOGÍA, no las quietas. La caché sigue siendo buena salvo a ≤alcance de la edición, así
        // que se usa (fusión, barata) y se marca sucia: se rehará exacta cuando el jugador deje de editar.
        if(S.k.gen !== (mc.gridGen|0)){ S.k.sucia = true; S.k.tocada = performance.now(); }
        sembrado = fusionaCache() >= 0;
      }
      S.sembrado = !!sembrado;      // hecho permanente, no contador: sobrevive a cero()
      C.ganadas = S.k.ultGanadas|0;
      C.rehorneos++; C.msOrig = t1 - t0; C.msSiembra = performance.now() - t1;
      mc._blkTexDirty = sembrado || dirtyA || mc._blkTexDirty;
    } else {
      mc._blkTexDirty = dirtyA;     // sin rehorneo no hay nada nuevo que subir
    }
    return r;
  });

  // 4b · el candado del forzado. `mcRecomputeHasGlow` pone `hasGlow=false` en un mapa cuyas únicas luces son
  //      estrellas de voxelesUI (no son ni estructura emisiva ni celda de rejilla, así que no las ve), y el
  //      render sólo sube el campo con `if(mc.hasGlow && mc._blkTexDirty)`. Sin esto, el primer re-mallado
  //      apaga las quietas EN SILENCIO — que es la otra mitad del fallo 4.
  envolver('mcRecomputeHasGlow', (orig, a) => {
    const r = orig.apply(null, a);
    if(S.quietas.length && API.emisoras) mc.hasGlow = true;
    return r;
  });

  // 5 · sólo para MEDIR. La subida de una textura 3D no aparece en ningún perfil de JS y es lo que hacía que
  //     «los fps suban mucho y el navegador apenas se refresque»: el coste es de la GPU, no del hilo.
  envolver('mcUploadBlkTex', (orig, a) => {
    const d = mc.dim; C.subidas++; C.bytes += d.x*d.y*d.z*4;
    return orig.apply(null, a);
  });

  mc._dynSig = null; mc._blEmiSig = null;
  if(mc.grid) mcComputeBlockLight();
}

// ── el mando ────────────────────────────────────────────────────────────────────────────────────────────────
const API = {
  // Pasadas idénticas seguidas antes de dar una luz por quieta. Con 8 y 60 fps son 133 ms: una partícula que
  // se para de verdad tarda eso en abaratarse, y una que vuela no se da por quieta nunca.
  tras: 8,
  get puesto(){ return !!(window.mcVoxUILuces && window.mcVoxUILuces._lqOrig); },
  // Cuánto espera el refresco exacto tras la ÚLTIMA edición, en ms. 0 = sin caché, siempre exacto (y 268 ms
  // de congelón por bloque, que es lo que hacía la v3).
  refresco: 900,
  // ¿las quietas ALUMBRAN el mundo (campo de bloque) o sólo se salen de la caja dinámica? Ver arriba.
  emisoras: true,
  emiten(v){
    if(v === undefined) return API.emisoras;
    const nuevo = !!v;
    if(nuevo === API.emisoras) return API.estado();
    API.emisoras = nuevo;
    // Cambiar de rama obliga a rehacer el campo del mundo: al apagar hay que BORRAR lo que las quietas
    // dejaron pegado (si no, alumbran para siempre sin que nadie las mantenga: Ley VII al revés).
    if(!nuevo){ S.hasGlowAntes = null; S.sembrado = false; }
    S.k.sig = null;                      // la caché se rehará cuando vuelvan a hacer falta
    mc._blEmiSig = null;
    if(typeof mcRecomputeHasGlow === 'function') mcRecomputeHasGlow();
    if(mc.grid) mcComputeBlockLight();
    return API.estado();
  },
  // ── EL VERIFICADOR ──────────────────────────────────────────────────────────────────────────────────────
  // La lección de esta tarde: dos veces di por buena una medida que era mentira. Esto no opina, mide. Guarda
  // lo que hay AHORA en el campo (lo que se está viendo), fuerza el rehorneo EXACTO —siembra directa, sin
  // caché— y compara celda a celda. Devuelve cuántas difieren y en cuántos NIVELES, que es la unidad en la
  // que se ve. Cero difs = el camino rápido es indistinguible del exacto.
  verifica(){
    if(!API.puesto) return 'luz-quietas: no está puesto (game.luzQuietas.on())';
    const BL = mc.blockLight;
    if(!BL || !S.quietas.length) return 'luz-quietas: aún no hay campo ni quietas que verificar';
    const antes = BL.slice();
    const t0 = performance.now();
    S.exacto = true;
    try { mc._blEmiSig = null; mcComputeBlockLight(); } finally { S.exacto = false; }
    const ms = performance.now() - t0;
    const N = antes.length >> 2, SUB = Math.max(1, MC_LUZ_SUB);
    let dif = 0, peor = 0, suma = 0, conLuz = 0;
    for(let i = 0; i < N; i++){
      const j = i*4, e = BL[j+3];
      if(e) conLuz++;
      const d = Math.abs(e - antes[j+3]);
      if(d){ dif++; suma += d; if(d > peor) peor = d; }
    }
    S.k.sig = null;   // el campo vivo ya es exacto; la caché no, que se rehaga en el próximo rehorneo
    const l = [
      '🔎 luz-quietas · VERIFICACIÓN contra el rehorneo exacto (' + ms.toFixed(1) + ' ms)',
      '  celdas con luz de bloque .. ' + conLuz.toLocaleString('es') + ' de ' + N.toLocaleString('es'),
      '  celdas que DIFIEREN ....... ' + dif.toLocaleString('es') +
        (dif ? '  (' + (100*dif/Math.max(1,conLuz)).toFixed(2) + ' % de las que tienen luz)' : ''),
      '  peor diferencia ........... ' + (peor/SUB).toFixed(2) + ' niveles' +
        (dif ? ' · media ' + (suma/dif/SUB).toFixed(2) : ''),
      dif ? '  ⚠️ el camino rápido NO coincide con el exacto. Si esto sale >0 con el mundo quieto, es un BUG'
          : '  ✅ indistinguible del exacto: el camino rápido no cambia ni una celda'
    ];
    const s = l.join('\n'); console.log(s); return { difieren: dif, conLuz, peorNiveles: peor/SUB, ms };
  },
  on(){ if(!API.puesto) instalar(); return API.estado(); },
  off(){
    if(API.puesto) desinstalar();
    // Ley VIII: la restauración también tiene que poder delatarse sola. Si esto sale con hasGlow=true en un
    // mapa sin emisores propios, el A/B que venga detrás NO vale y hay que decirlo aquí, no descubrirlo
    // tres medidas después.
    let luz = 0; const BL = mc.blockLight;
    if(BL) for(let j = 3; j < BL.length; j += 4) if(BL[j]){ luz++; }
    return 'luz-quietas: motor original restaurado · mc.hasGlow=' + mc.hasGlow +
           ' · celdas con luz de bloque ' + luz.toLocaleString('es') +
           (luz && !mc.hasGlow ? ' (horneadas pero invisibles: hasGlow=false)' : '');
  },
  // Suelta los 18 MB de la caché. off() ya NO lo hace (ver desinstalar): así el A/B va seguido.
  suelta(){
    const mb = S.k.idx ? (S.k.idx.length*20/1048576).toFixed(0) : '0';
    S.k.idx = S.k.bl = S.k.bd = S.k.or = S.k.di = S.k.mx = null;
    S.k.sig = null; S.k.gen = null; S.k.n = 0; S.k.celdas = 0; S.k.ultGanadas = 0;
    return 'luz-quietas: caché soltada (' + mb + ' MB) · el próximo rehorneo la rehará';
  },
  cero,                                   // pone los contadores a cero para medir un tramo concreto
  estado(){
    const D = mc.dynLight;
    const nQ = S.quietas.length/4, nM = (S.moviles||[]).length/4, nT = (S.todas||[]).length/4;
    const caja = D ? D.W*D.H*D.P : 0;
    const t = Math.max(1, C.ticks);
    const mb = C.bytes / 1048576;
    const l = [
      '💡 luz-quietas v7 · ' + (API.puesto ? 'PUESTO' : 'quitado') + ' · tras=' + API.tras + ' · ' + C.ticks + ' ticks medidos',
      '  luces de voxelesUI ....... ' + nT + '  →  quietas ' + nQ + ' (campo del MUNDO) · móviles ' + nM + ' (en la caja)',
      '  caja dinámica ............ ' + caja.toLocaleString('es') + ' celdas' + (D ? ' = ' + D.W + '×' + D.H + '×' + D.P : '') +
        ' · semillas ' + (D ? D.luces : 0) + '/' + MC_DYN_SEMILLAS,
      '  paso del campo ........... sub ' + MC_LUZ_SUB + ' (alcance máx. de las quietas: ' + S.lvQ + ')',
      '  ── EL CAMPO DEL MUNDO, POR TICK (lo que la v1 no medía) ──',
      '  mcComputeBlockLight ...... ' + (C.cbl/t).toFixed(3) + ' llamadas/tick · rehorneos reales ' + C.rehorneos +
        ' (' + (100*C.rehorneos/Math.max(1,C.cbl)).toFixed(1) + ' % de las llamadas)',
      '  coste del último rehorneo  ' + (C.msOrig+C.msSiembra).toFixed(1) + ' ms = mundo ' + C.msOrig.toFixed(1) +
        ' + estrellas ' + C.msSiembra.toFixed(1),
      // ⚠️ S.k.ultGanadas y NO C.ganadas: cero() pone los contadores a 0 y esta línea salía «sembradas (0
      // celdas)» justo después de medir un tramo limpio. Un hecho permanente no se lee de un contador.
      '  quietas en el campo ...... ' + (S.sembrado ? 'SÍ, sembradas (' + (S.k.ultGanadas|0).toLocaleString('es') +
        ' celdas) · 0 rehorneos/tick es el AHORRO, no un fallo (Ley VII)' : 'NO — el mundo no las lleva'),
      '  censo (coste FIJO) ....... ' + (C.msCenso/t).toFixed(3) + ' ms/tick · ' + nT + ' luces miradas por frame',
      '  textura 3D a la GPU ...... ' + (C.subidas/t).toFixed(3) + ' subidas/tick · ' + (mb/t).toFixed(2) +
        ' MB/tick (' + mb.toFixed(0) + ' MB en total)',
      '  cambios del paso ......... ' + C.cambiosSub + (S.conSub ? '' : '  (sin mcLuzSubAjusta: app.js sin REQ-LUZ4)'),
      '  mc.hasGlow ............... ' + mc.hasGlow + (S.hasGlowAntes !== null ? ' (forzado; venía ' + S.hasGlowAntes + ')' : ''),
      '  ── LA CACHÉ DE LAS QUIETAS (lo que quita el congelón al editar) ──',
      '  horneada ................. ' + (S.k.horneos|0) + ' veces · la última ' + (S.k.ms||0).toFixed(1) + ' ms' +
        (S.k.idx ? ' · ' + (S.k.celdas|0).toLocaleString('es') + ' celdas · ocupa ' +
          (S.k.idx.length*20/1048576).toFixed(0) + ' MB' : ' · SIN HORNEAR'),
      // v5: TRES relojes. El de la v4 era uno solo y se leía como «fusión» aunque hubiera corrido el horneo.
      '  fusión (lo que se paga) .. ' + (C.msFusion||0).toFixed(1) + ' ms la última · media ' +
        ((C.msFusionTot||0)/Math.max(1, C.nFusiones|0)).toFixed(1) + ' ms en ' + (C.nFusiones|0) + ' fusiones · ' +
        (C.ganadas|0).toLocaleString('es') + ' celdas ganadas',
      '  horneo / exacta .......... ' + (C.msHornear||0).toFixed(1) + ' ms / ' + (C.msExacto||0).toFixed(1) +
        ' ms (0 = esa rama no corrió en el último rehorneo)',
      '  refrescos diferidos ...... ' + (C.refrescos|0) + ' · espera ' + API.refresco + ' ms tras la última edición' +
        (S.k.sucia ? '  ⏳ SUCIA ahora mismo' : ''),
      '  ¿coincide con el exacto? . game.luzQuietas.verifica()',
    ];
    const av = [];
    if(!API.puesto) av.push('⚠️ DESINSTALADO (game.luzQuietas.on() para volver a ponerlo)');
    // El censo necesita `tras` pasadas para arrancar. Mirar el informe justo después de on() da 0 quietas y
    // NINGUNA alarma, que es lo que hizo que la tirada del 2026-08-21 no contestara a la única pregunta que
    // importaba. El informe se mira DESPUÉS de medir, no antes.
    if(API.puesto && C.ticks < API.tras) av.push('⚠️ sólo ' + C.ticks + ' ticks: el censo aún no ha repartido ' +
      '(necesita ' + API.tras + '). Este informe TODAVÍA NO DICE NADA — vuelve a mirarlo DESPUÉS de la sonda.');
    // LA ALARMA QUE FALTABA (v3). Éstas son las dos formas de «ir rapidísimo porque no alumbro»: la medida
    // que engaña. Si saltan, el A/B de fps NO vale — se están comparando dos escenas distintas, no dos
    // implementaciones de la misma. Mandamiento 2: las quietas son emisores y tienen que emitir.
    // Con `emiten(false)` que NO alumbren es lo pedido, no un fallo: la alarma que gritara ahí estaría
    // mintiendo al revés. Pero la rama sigue sin ser comparable en fps, y eso hay que decirlo IGUAL.
    if(nQ && !API.emisoras) av.push('ℹ️ emiten(false): las quietas salen de la caja pero NO alumbran el mundo. ' +
      'Se ve distinto que off() ⇒ estos fps miden el ahorro de CPU sin el coste de GPU, no la escena final.');
    if(nQ && API.emisoras && !mc.hasGlow) av.push('🛑 hay ' + nQ + ' quietas y mc.hasGlow=false: el render NUNCA sube el campo ' +
      'del mundo ⇒ NO ALUMBRAN. Los fps de esta rama no son comparables.');
    // v6: NO se mira `C.rehorneos` (lo pone a cero `cero()`, y entonces la alarma acusaba justo al caso bueno:
    // campo ya sembrado + cero rehorneos = Ley VII, que es EL AHORRO del ticket). Se mira el hecho: ¿están
    // las quietas dentro del campo del mundo ahora mismo?
    if(nQ && API.emisoras && !S.sembrado && C.ticks > 30) av.push('🛑 ' + nQ +
      ' quietas y el campo del mundo NO las lleva ⇒ NO ALUMBRAN. Los fps de esta rama no son comparables.');
    if(C.subidas/t > 0.2) av.push('⚠️ el campo del mundo se sube a la GPU ' + (C.subidas/t).toFixed(2) +
      ' veces por tick: eso es GPU, NO JS ⇒ los fps del marcador mienten. Mira los MB/tick.');
    if(C.cambiosSub > 3) av.push('⚠️ el paso del campo cambia ' + C.cambiosSub + ' veces: huele a realimentación, ' +
      'y cada cambio rehornea LOS DOS campos enteros.');
    if(C.rehorneos > t*0.1) av.push('⚠️ el campo del mundo se rehornea en más del 10 % de los ticks: el conjunto ' +
      '«quieto» no se está estabilizando (¿sube `tras`?).');
    if((mc.glowFocus||0) > 0 && nQ) av.push('ℹ️ glowFocus=' + mc.glowFocus + ' y hay quietas: punto B de la cabecera (orden de las pasadas)');
    if(mc.fpsMax) av.push('ℹ️ game.fpsMax=' + mc.fpsMax + ' está puesto: el marcador de fps NO mide el refresco real');
    console.log(l.concat(av.map(a => '  ' + a)).join('\n'));
    return { puesto:API.puesto, quietas:nQ, moviles:nM, caja, sub:MC_LUZ_SUB,
             subidasPorTick:+(C.subidas/t).toFixed(3), mbPorTick:+(mb/t).toFixed(2),
             rehorneos:C.rehorneos, cambiosSub:C.cambiosSub, ticks:C.ticks };
  },
};
game.luzQuietas = API;

if(API.puesto) desinstalar();     // re-ejecutable: nunca dos capas de parches
instalar();
console.log('💡 luz-quietas v7 instalado. Anda un poco y luego: game.luzQuietas.estado()\n' +
            '   Mide un tramo limpio con game.luzQuietas.cero() y vuelve a mirar estado().\n' +
            '   A/B: game.luzQuietas.off() ↔ .on(), con performance/consola_donde_va_el_frame.js.');
})();
